/**
 * Generic Data-Driven Real-DLL Function Fixture Loader & Strict Replay Helper (`M0b`).
 *
 * Loads `.ndjson.gz` (or `.ndjson`) fixtures generated by `tools/oracle/vectors/fn-emitter.c`
 * and replays every recorded test vector against a TypeScript kernel port over `ReplayMemory113c`
 * (`SparseMemory113c` with strict write-set tracking and deterministic arena allocation replay).
 *
 * Enforces:
 * 1. Header `kind === "D2FNVEC"`, `version === 1`, and `requestSha256` + `pre` image parity against `.req.json`.
 * 2. Fault/FogAssert parity: if the DLL vector faulted or triggered `FOG.#10024`, TS must throw; if the DLL
 *    returned normally, TS must return a finite number matching `ret | 0` (when `conv.returns === "eax"`)
 *    or `undefined` (when `conv.returns === "void"`).
 * 3. `espDelta` parity against `conv.calleePops`.
 * 4. Exact arena allocation sequence (`size` and returned VA) on `m.alloc(size)` and `m.free(ptr)` parity.
 * 5. Byte-for-byte `post` memory comparison across all images, globals, dumps, and allocations.
 * 6. Zero rogue writes outside recorded `post` / `alloc` spans.
 * 7. Built-in negative controls (`expectMutantsKilled113c`) proving the replay test fails when
 *    return values, memory writes, or fault behavior are mutated.
 */
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { gunzipSync } from 'node:zlib'
import type { FieldLayout113c } from '../../../src/d2kern-113c/mem/layout.generated.ts'
import {
  SparseMemory113c,
  type Memory113c,
} from '../../../src/d2kern-113c/mem/sparse-memory.ts'
import {
  compileFnRequest113c,
  type CompiledFnRequest113c,
  type FnFixtureHeader113c,
} from './fn-request.ts'

export type { FnFixtureHeader113c }

export interface FnRegs113c {
  readonly eax: number
  readonly ecx: number
  readonly edx: number
  readonly ebx: number
  readonly esi: number
  readonly edi: number
}

export interface FnFaultRecord113c {
  readonly kind: 'exception' | 'fogAssert'
  readonly code: string
  readonly eipVa: string
  readonly avAddr?: string
  readonly avWrite?: number
  readonly line?: number
}

export interface FnVectorRecord113c {
  readonly idx: number
  readonly label: string
  readonly fn: string
  readonly va: number
  readonly frame: number
  readonly args: readonly number[]
  readonly regs: FnRegs113c
  readonly ret?: number
  readonly edx?: number
  readonly espDelta: number
  readonly clobbers: readonly string[]
  readonly fault?: FnFaultRecord113c
  readonly pre: readonly (readonly [number, string])[]
  readonly post: readonly (readonly [number, string])[]
  readonly allocs: readonly (readonly [number, number])[]
  readonly frees: readonly number[]
}

export interface FnFixture113c {
  readonly fixturePath: string
  readonly decompressedSha256: string
  readonly header: FnFixtureHeader113c
  readonly records: readonly FnVectorRecord113c[]
  readonly compiledRequest?: CompiledFnRequest113c
}

export type FnInvoker113c = (
  m: ReplayMemory113c,
  args: readonly number[],
  regs: FnRegs113c,
  rec: FnVectorRecord113c,
) => number | void

export interface FnReplayReport113c {
  readonly total: number
  readonly passed: number
  readonly faults: number
  readonly failures: readonly string[]
}

function toHex32(v: number): string {
  return `0x${(v >>> 0).toString(16).padStart(8, '0')}`
}

/**
 * Strict replay memory over `SparseMemory113c`:
 * - Reading any unmapped byte throws (`SparseMemory113c: read of unloaded byte ...`).
 * - Writing any byte records its 32-bit address in `writtenBytes`.
 * - Calling `alloc(size)` pops the next `[wantSize, recAddr]` recorded from `Fog.#10042/#10045`
 *   in the real DLL and returns `recAddr` after zero-initializing `[recAddr, recAddr + size)`.
 */
export class ReplayMemory113c extends SparseMemory113c implements Memory113c {
  readonly writtenBytes = new Set<number>()
  readonly allocQueue: Array<readonly [number, number]> = []
  readonly allocSpans: Array<readonly [number, number]> = []
  readonly freedPtrs: number[] = []
  private trackWrites = true
  private suppressWrites = false

  constructor(opts?: { readonly suppressWrites?: boolean }) {
    super()
    this.suppressWrites = opts?.suppressWrites ?? false
  }

  loadHexAt(base: number, hex: string): void {
    const prevTrack = this.trackWrites
    const prevSuppress = this.suppressWrites
    this.trackWrites = false
    this.suppressWrites = false
    try {
      const buf = Buffer.from(hex, 'hex')
      const addr = base >>> 0
      super.loadBlock(addr, new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength))
    } finally {
      this.trackWrites = prevTrack
      this.suppressWrites = prevSuppress
    }
  }

  override setU8(p: number, v: number): void {
    if (this.suppressWrites) return
    const addr = p >>> 0
    if (this.trackWrites) {
      this.writtenBytes.add(addr)
    }
    super.setU8(addr, v)
  }

  override setU16(p: number, v: number): void {
    if (this.suppressWrites) return
    const addr = p >>> 0
    if (this.trackWrites) {
      this.writtenBytes.add(addr)
      this.writtenBytes.add((addr + 1) >>> 0)
    }
    super.setU16(addr, v)
  }

  override setU32(p: number, v: number): void {
    if (this.suppressWrites) return
    const addr = p >>> 0
    if (this.trackWrites) {
      this.writtenBytes.add(addr)
      this.writtenBytes.add((addr + 1) >>> 0)
      this.writtenBytes.add((addr + 2) >>> 0)
      this.writtenBytes.add((addr + 3) >>> 0)
    }
    super.setU32(addr, v)
  }

  override fill(p: number, len: number, v: number): void {
    if (this.suppressWrites) return
    const addr = p >>> 0
    if (this.trackWrites) {
      for (let i = 0; i < len; i++) {
        this.writtenBytes.add((addr + i) >>> 0)
      }
    }
    super.fill(addr, len, v)
  }

  override set(base: number, f: FieldLayout113c, v: number, index = 0): void {
    if (base === 0) throw new Error('SparseMemory113c: NULL base')
    if (index < 0 || index >= f.count) {
      throw new Error(`SparseMemory113c: index ${index} outside 0..${f.count - 1}`)
    }
    const width = f.type === 'u8' ? 1 : f.type === 'u16' ? 2 : 4
    const p = (base + f.off + index * width) >>> 0
    if (width === 1) this.setU8(p, v)
    else if (width === 2) this.setU16(p, v)
    else this.setU32(p, v)
  }

  w8(p: number, v: number): void {
    this.setU8(p, v)
  }

  w16(p: number, v: number): void {
    this.setU16(p, v)
  }

  w32(p: number, v: number): void {
    this.setU32(p, v)
  }

  override alloc(size: number): number {
    const next = this.allocQueue.shift()
    if (next === undefined) {
      throw new Error(`Unexpected alloc(${size}): DLL did not allocate more blocks`)
    }
    const [wantSize, rawAddr] = next
    const recAddr = rawAddr >>> 0
    if (size !== wantSize) {
      throw new Error(
        `alloc size mismatch: TS requested ${size}, DLL allocated ${wantSize} at ${toHex32(recAddr)}`,
      )
    }
    const prevTrack = this.trackWrites
    const prevSuppress = this.suppressWrites
    this.trackWrites = false
    this.suppressWrites = false
    try {
      super.loadBlock(recAddr, new Uint8Array(size))
    } finally {
      this.trackWrites = prevTrack
      this.suppressWrites = prevSuppress
    }
    if (!this.suppressWrites) {
      for (let i = 0; i < size; i++) {
        this.writtenBytes.add((recAddr + i) >>> 0)
      }
    }
    this.allocSpans.push([recAddr, (recAddr + size) >>> 0])
    return recAddr
  }

  free(ptr: number): void {
    this.freedPtrs.push(ptr >>> 0)
  }
}

/**
 * Loads a `.ndjson.gz` (or `.ndjson`) fixture from disk and optionally verifies it against
 * its source `.req.json` request file (`requestSha256`, `va`, `count`, and `pre` images).
 */
export function loadFnFixture113c(
  fixturePath: string,
  requestPath?: string,
): FnFixture113c {
  const rawBytes = readFileSync(fixturePath)
  const decompressedBuf = fixturePath.endsWith('.gz') ? gunzipSync(rawBytes) : rawBytes
  const decompressedSha256 = createHash('sha256').update(decompressedBuf).digest('hex')
  const text = decompressedBuf.toString('utf8')
  const lines = text
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l.length > 0)
  if (lines.length < 2) {
    throw new Error(`Fixture ${fixturePath} must contain a header line and >= 1 vector line`)
  }
  const header = JSON.parse(lines[0]!) as FnFixtureHeader113c
  if (header.kind !== 'D2FNVEC' || header.version !== 1) {
    throw new Error(
      `Unsupported fixture header in ${fixturePath}: kind=${String(header.kind)} version=${String(header.version)}`,
    )
  }
  const records = lines.slice(1).map((line) => JSON.parse(line) as FnVectorRecord113c)
  if (records.length !== header.count || records.length === 0) {
    throw new Error(
      `Fixture ${fixturePath}: header.count=${header.count} !== actual records=${records.length}`,
    )
  }

  let compiledRequest: CompiledFnRequest113c | undefined
  if (requestPath !== undefined) {
    compiledRequest = compileFnRequest113c(requestPath)
    if (header.requestSha256.toLowerCase() !== compiledRequest.header.requestSha256.toLowerCase()) {
      throw new Error(
        `Fixture ${fixturePath} requestSha256 mismatch vs ${requestPath}: ` +
          `fixture=${header.requestSha256}, request=${compiledRequest.header.requestSha256}`,
      )
    }
    if (header.va.toLowerCase() !== compiledRequest.va.toLowerCase()) {
      throw new Error(
        `Fixture ${fixturePath} va=${header.va} !== request=${compiledRequest.va}`,
      )
    }
    if (records.length !== compiledRequest.vectors.length) {
      throw new Error(
        `Fixture ${fixturePath} records=${records.length} !== request vectors=${compiledRequest.vectors.length}`,
      )
    }
    for (let i = 0; i < records.length; i++) {
      const rec = records[i]!
      const reqVec = compiledRequest.vectors[i]!
      if (rec.label !== reqVec.label) {
        throw new Error(
          `Vector #${i} label mismatch: fixture=${rec.label}, request=${reqVec.label}`,
        )
      }
      const preByAddr = new Map<number, string>()
      for (const [addr, hex] of rec.pre) {
        preByAddr.set(addr >>> 0, hex.toLowerCase())
      }
      for (let imgIdx = 0; imgIdx < compiledRequest.images.length; imgIdx++) {
        const img = compiledRequest.images[imgIdx]!
        const gotHex = preByAddr.get(img.addr >>> 0)
        const wantHex = Buffer.from(reqVec.imageBytes[imgIdx]!).toString('hex').toLowerCase()
        if (gotHex !== wantHex) {
          throw new Error(
            `Vector #${i} (${rec.label}): pre[${toHex32(img.addr)}] (${img.name}) does not match compiled request image`,
          )
        }
      }
    }
  }

  return {
    fixturePath,
    decompressedSha256,
    header,
    records,
    ...(compiledRequest !== undefined ? { compiledRequest } : {}),
  }
}

function replayFixtureInternal(
  fx: FnFixture113c,
  invoke: FnInvoker113c,
  opts?: { readonly suppressWrites?: boolean },
): FnReplayReport113c {
  let passed = 0
  let faults = 0
  const failures: string[] = []

  for (const rec of fx.records) {
    const m = new ReplayMemory113c(opts)
    for (const [rawAddr, hex] of rec.pre) {
      m.loadHexAt(rawAddr >>> 0, hex)
    }
    for (const [sz, rawAddr] of rec.allocs ?? []) {
      m.allocQueue.push([sz, rawAddr >>> 0])
    }

    let tsRet: unknown
    let tsErr: unknown = null
    try {
      tsRet = invoke(m, rec.args, rec.regs, rec)
    } catch (e) {
      tsErr = e
    }

    if (rec.fault !== undefined) {
      faults++
      if (tsErr === null) {
        failures.push(
          `vec #${rec.idx} (${rec.label}): DLL faulted (${rec.fault.kind} ${rec.fault.code} at ${rec.fault.eipVa}), but TS returned ${String(tsRet)}`,
        )
      } else {
        passed++
      }
      continue
    }

    if (tsErr !== null) {
      failures.push(
        `vec #${rec.idx} (${rec.label}): TS threw ${(tsErr as Error).message ?? String(tsErr)}, but DLL returned ${String(rec.ret)}`,
      )
      continue
    }

    if (rec.espDelta !== fx.header.conv.calleePops) {
      failures.push(
        `vec #${rec.idx} (${rec.label}): DLL espDelta=${rec.espDelta} !== header calleePops=${fx.header.conv.calleePops}`,
      )
      continue
    }

    if (fx.header.conv.returns === 'eax') {
      if (typeof tsRet !== 'number' || !Number.isFinite(tsRet)) {
        failures.push(
          `vec #${rec.idx} (${rec.label}): conv.returns='eax' requires finite number return, got ${String(tsRet)}`,
        )
        continue
      }
      if (rec.ret === undefined) {
        failures.push(`vec #${rec.idx} (${rec.label}): missing ret in fixture record`)
        continue
      }
      const gotEax = tsRet | 0
      const wantEax = rec.ret | 0
      if (gotEax !== wantEax) {
        failures.push(
          `vec #${rec.idx} (${rec.label}): eax mismatch: TS=${toHex32(gotEax)} (${gotEax}) vs DLL=${toHex32(wantEax)} (${wantEax})`,
        )
        continue
      }
    } else {
      if (tsRet !== undefined) {
        failures.push(
          `vec #${rec.idx} (${rec.label}): conv.returns='void' requires undefined return, got ${String(tsRet)}`,
        )
        continue
      }
    }

    if (m.allocQueue.length !== 0) {
      failures.push(
        `vec #${rec.idx} (${rec.label}): TS left ${m.allocQueue.length} unconsumed DLL allocation(s)`,
      )
      continue
    }

    if (rec.frees.length > 0 && m.freedPtrs.length > 0) {
      if (m.freedPtrs.length !== rec.frees.length) {
        failures.push(
          `vec #${rec.idx} (${rec.label}): free count mismatch: TS=${m.freedPtrs.length} vs DLL=${rec.frees.length}`,
        )
        continue
      }
      let freeMismatch = false
      for (let i = 0; i < rec.frees.length; i++) {
        if ((m.freedPtrs[i]! >>> 0) !== (rec.frees[i]! >>> 0)) {
          failures.push(
            `vec #${rec.idx} (${rec.label}): free[${i}] mismatch: TS=${toHex32(m.freedPtrs[i]!)} vs DLL=${toHex32(rec.frees[i]!)}`,
          )
          freeMismatch = true
          break
        }
      }
      if (freeMismatch) continue
    }

    const expectedSpans: Array<readonly [number, number]> = [...m.allocSpans]
    let postMismatch = false
    for (const [rawBase, wantHex] of rec.post) {
      const base = rawBase >>> 0
      const want = Buffer.from(wantHex, 'hex')
      expectedSpans.push([base, (base + want.length) >>> 0])
      for (let i = 0; i < want.length; i++) {
        const addr = (base + i) >>> 0
        const got = m.u8(addr)
        if (got !== want[i]) {
          failures.push(
            `vec #${rec.idx} (${rec.label}): post memory mismatch at ${toHex32(addr)} (${toHex32(base)}+0x${i.toString(16)}): ` +
              `TS=0x${got.toString(16).padStart(2, '0')} vs DLL=0x${want[i]!.toString(16).padStart(2, '0')}`,
          )
          postMismatch = true
          break
        }
      }
      if (postMismatch) break
    }
    if (postMismatch) continue

    let rogueWrite = false
    for (const w of m.writtenBytes) {
      let inSpan = false
      for (const [lo, hi] of expectedSpans) {
        if (w >= lo && w < hi) {
          inSpan = true
          break
        }
      }
      if (!inSpan) {
        failures.push(
          `vec #${rec.idx} (${rec.label}): rogue write at ${toHex32(w)} outside recorded post/alloc spans`,
        )
        rogueWrite = true
        break
      }
    }
    if (rogueWrite) continue

    passed++
  }

  return {
    total: fx.records.length,
    passed,
    faults,
    failures,
  }
}

/**
 * Replays every vector in `fx` against `invoke` and returns a structured `FnReplayReport113c`.
 */
export function replayFnFixture113c(
  fx: FnFixture113c,
  invoke: FnInvoker113c,
): FnReplayReport113c {
  return replayFixtureInternal(fx, invoke)
}

/**
 * Asserts that `fx` meets `minVectors` / `minFaults` requirements and replays with zero failures.
 */
export function expectFnFixtureMatches113c(
  fx: FnFixture113c,
  invoke: FnInvoker113c,
  opts?: {
    readonly minVectors?: number
    readonly minCases?: number
    readonly minFaults?: number
  },
): FnReplayReport113c {
  const minVectors = opts?.minVectors ?? opts?.minCases ?? 1
  const minFaults = opts?.minFaults ?? 0
  if (fx.records.length < minVectors) {
    throw new Error(
      `Fixture ${fx.fixturePath} has ${fx.records.length} vectors (< minVectors=${minVectors})`,
    )
  }
  const report = replayFnFixture113c(fx, invoke)
  if (report.failures.length > 0) {
    throw new Error(
      `Fixture ${fx.fixturePath} failed (${report.failures.length}/${report.total}):\n  ` +
        report.failures.slice(0, 5).join('\n  '),
    )
  }
  if (report.faults < minFaults) {
    throw new Error(
      `Fixture ${fx.fixturePath} has ${report.faults} fault vectors (< minFaults=${minFaults})`,
    )
  }
  if (report.passed - report.faults < 1) {
    throw new Error(
      `Fixture ${fx.fixturePath} has 0 non-fault passing vectors (all ${report.faults} vectors faulted)`,
    )
  }
  return report
}

/**
 * Negative-control guard: verifies that built-in and caller-supplied mutants of `invoke`
 * are killed (produce >= 1 failure in `replayFnFixture113c`).
 */
export function expectMutantsKilled113c(
  fx: FnFixture113c,
  invoke: FnInvoker113c,
  mutants: ReadonlyArray<readonly [string, (inv: FnInvoker113c) => FnInvoker113c]> = [],
): void {
  const allMutants: Array<readonly [string, (inv: FnInvoker113c) => FnInvoker113c]> = []

  if (fx.header.conv.returns === 'eax') {
    allMutants.push([
      'eax+1',
      (inv) => (m, args, regs, rec) => {
        const r = inv(m, args, regs, rec)
        return (((r as number) + 1) | 0)
      },
    ])

    const hasNonZeroEax = fx.records.some(
      (rec) => rec.fault === undefined && rec.ret !== undefined && (rec.ret | 0) !== 0,
    )
    if (hasNonZeroEax) {
      allMutants.push([
        'eax=0',
        (inv) => (m, args, regs, rec) => {
          inv(m, args, regs, rec)
          return 0
        },
      ])
    }
  } else {
    allMutants.push([
      'void-returns-number',
      (inv) => (m, args, regs, rec) => {
        inv(m, args, regs, rec)
        return 1
      },
    ])
  }

  // Mutant: flip one byte in the first post block of any non-fault vector
  const hasPostBlock = fx.records.some((rec) => rec.fault === undefined && rec.post.length > 0)
  if (hasPostBlock) {
    allMutants.push([
      'flip-one-post-byte',
      (inv) => (m, args, regs, rec) => {
        const r = inv(m, args, regs, rec)
        if (rec.post.length > 0) {
          const [base] = rec.post[0]!
          const a = base >>> 0
          m.setU8(a, m.u8(a) ^ 0xff)
        }
        return r
      },
    ])
  }

  // Mutant: extra rogue write 1 byte past the first post block (or at 0x20FF0000)
  allMutants.push([
    'rogue-write-past-post',
    (inv) => (m, args, regs, rec) => {
      const r = inv(m, args, regs, rec)
      if (rec.post.length > 0) {
        const [base, hex] = rec.post[0]!
        const end = ((base >>> 0) + hex.length / 2) >>> 0
        m.setU8(end, 0xa5)
      } else {
        m.setU8(0x20ff0000, 0xa5)
      }
      return r
    },
  ])

  // Mutant: throw on the first non-fault vector
  allMutants.push([
    'throw-on-first-ok-vector',
    (inv) => (m, args, regs, rec) => {
      if (rec.fault === undefined) {
        throw new Error('synthetic mutant throw')
      }
      return inv(m, args, regs, rec)
    },
  ])

  // Mutant: drop all memory writes if any non-fault vector actually mutates pre->post or allocates
  const hasMutatedPost = fx.records.some((rec) => {
    if (rec.fault !== undefined) return false
    if (rec.allocs.length > 0) return true
    const preMap = new Map<number, string>()
    for (const [a, h] of rec.pre) preMap.set(a >>> 0, h.toLowerCase())
    for (const [a, h] of rec.post) {
      if (preMap.get(a >>> 0) !== h.toLowerCase()) return true
    }
    return false
  })
  if (hasMutatedPost) {
    const dropRep = replayFixtureInternal(fx, invoke, { suppressWrites: true })
    if (dropRep.failures.length === 0) {
      throw new Error(
        `Mutant "drop-all-writes" SURVIVED against fixture ${fx.fixturePath}`,
      )
    }
  }

  for (const mSpec of mutants) {
    allMutants.push(mSpec)
  }

  for (const [name, makeMutant] of allMutants) {
    const rep = replayFnFixture113c(fx, makeMutant(invoke))
    if (rep.failures.length === 0) {
      throw new Error(`Mutant "${name}" SURVIVED against fixture ${fx.fixturePath}`)
    }
  }
}
